import {Client} from "@modelcontextprotocol/client";
import {StdioClientTransport} from "@modelcontextprotocol/client/stdio";
import {createHash} from "node:crypto";
import {join} from "node:path";
const cwd=process.cwd();
const transport=new StdioClientTransport({command:process.execPath,args:[join(cwd,"bin","pc-browser-tab-mcp-stdio.js")],cwd,env:{...process.env,PC_CONTROL_ENABLE_BROWSER_TAB_CAPTURE:"1",PC_CONTROL_BROWSER_CDP_ALLOWED_PORTS:"17410,17447"},stderr:"pipe"});
const client=new Client({name:"local-browser-cdp-canary",version:"1.0.0"});
const results=[];
try{
 await client.connect(transport);
 const advertised=await client.listTools();
 const names=advertised.tools.map(t=>t.name).sort();
 if(JSON.stringify(names)!==JSON.stringify(["browser.tab.capture","browser.tab.list"]))throw Error("unexpected_tools");
 for(const port of [17410,17447]){
 const listed=await client.callTool({name:"browser.tab.list",arguments:{port}});
 if(listed.isError)throw Error("listing_failure");
 const tabs=JSON.parse(listed.content.find(x=>x.type==="text").text).tabs;
 const target=tabs.find(x=>new URL(x.url).hostname==="127.0.0.1");
 if(!target)throw Error("no_local_dashboard");
 const capture=await client.callTool({name:"browser.tab.capture",arguments:{port,target_id:target.target_id,expected_url:target.url}});
 if(capture.isError)throw Error("capture_failed");
 const img=capture.content.find(x=>x.type==="image");
 const m=JSON.parse(capture.content.find(x=>x.type==="text").text);
 if(!img||img.mimeType!=="image/png")throw Error("no_mcp_png_image");
 const bytes=Buffer.from(img.data,"base64");
 const sha=createHash("sha256").update(bytes).digest("hex");
 if(sha!==m.sha256||!bytes.subarray(0,8).equals(Buffer.from("89504e470d0a1a0a","hex")))throw Error("png_sha_invalid");
 results.push({port,imageType:img.type,mime:img.mimeType,shaVerified:true,width:m.width,height:m.height,bytes:bytes.length,textPixelsLeaked:capture.content.find(x=>x.type==="text").text.includes(img.data)});
 }
 console.log(JSON.stringify({connected:true,toolNames:names,results}));
}catch(e){console.log(JSON.stringify({connected:false,errorCode:e.code||e.name||"Error"}));process.exitCode=1}finally{await client.close().catch(()=>{});}
